# cache.rb

class Cache
  def initialize(packer: nil)
    @packer = packer || Object.new.tap do |o|
      def o.dump(payload)
        payload
      end
      def o.load(data)
        data
      end
    end
    @store = {}
    @stale_keys = {}
  end

  # Store payload under key. If stale is true, mark this entry as stale.
  def write(key, payload, stale: false)
    # Serialize payload using the packer
    serialized_payload = @packer.dump(payload)

    @store[key] = {
      payload: serialized_payload,
      stale: stale
    }

    nil
  end

  # Return the payload most recently written under key, or nil if key was never
  # written or has been removed by #sweep.
  def read(key)
    if @store.key?(key)
      entry = @store[key]
      # Deserialize payload using the packer
      @packer.load(entry[:payload])
    else
      nil
    end
  end

  # Remove every entry whose #write call passed stale: true, leaving every other entry in place.
  def sweep
    keys_to_remove = @store.select do |key, entry|
      entry[:stale]
    end.keys

    keys_to_remove.each do |key|
      @store.delete(key)
    end

    nil
  end
end
