class Counter
  attr_reader :value

  def initialize
    @value = 0
    @step = 1
    @override_step = nil
  end

  def bump
    @value += current_step
    self
  end

  def current_step
    if @override_step != nil
      @override_step
    else
      @step
    end
  end

  def with_step(step)
    old_override = @override_step
    @override_step = step
    begin
      yield self if block_given?
    ensure
      @override_step = old_override
    end
    self
  end

  def initialize_copy(other)
    super
    @value = other.value
    @step = other.instance_variable_get(:@step)
    @override_step = other.instance_variable_get(:@override_step)
  end
end
