class SparseArray
  include Enumerable

  def initialize
    @data = {}
    @indices = []
  end

  def []=(index, value)
    @data[index] = value
    # Rebuild the sorted indices array
    # We can optimize, but for correctness simplicity, rebuild
    @indices = @data.keys.sort
  end

  def [](index)
    @data[index]
  end

  def each
    @indices.each do |index|
      yield(@data[index])
    end
    self
  end

  def count
    @data.size
  end

  # Enumerable methods like map, select, sum, etc. will work via each
end
