class Registry
  def initialize
    @objects = []
    @object_ids = {}
  end

  def register(obj)
    obj_id = obj.object_id
    unless @object_ids.key?(obj_id)
      @objects << obj
      @object_ids[obj_id] = true
    end
    self
  end

  def registered?(obj)
    @object_ids.key?(obj.object_id)
  end

  def size
    @objects.size
  end

  def to_a
    @objects.dup
  end
