  def initialize
    @objects = []
  end

  def register(obj)
    # Only add if this exact object (identity) hasn't been registered before
    unless @objects.any? { |existing| existing.equal?(obj) }
      @objects << obj
    end
    self
  end

  def registered?(obj)
    @objects.any? { |existing| existing.equal?(obj) }
  end

  def size
    @objects.size
  end

  def to_a
