# Define the OpenRecord class
class OpenRecord
  def initialize(**attrs)
    @store = {}
    attrs.each do |key, value|
      @store[key] = value
      define_getter(key)
      define_setter(key)
    end
  end

  def respond_to?(name, include_private = false)
    # Check if it's a getter or setter that exists in our store
    if name.to_s.end_with?('=')
      attr_name = name.to_s.sub(/=\z/, '').to_sym
      @store.key?(attr_name) || super(name, include_private)
    else
      attr_sym = name.to_sym
      @store.key?(attr_sym) || super(name, include_private)
    end
  end

  private

  def define_getter(attr_name)
    singleton_class.define_method(attr_name) do
      if @store.key?(attr_name)
        @store[attr_name]
      else
        raise NoMethodError, "undefined method `#{attr_name}' for #{self.class.name}"
      end
    end
  end

  def define_setter(attr_name)
    singleton_class.define_method(:"#{attr_name}=") do |value|
      @store[attr_name] = value
      # Also define getter and setter for this new attribute if not already defined
      define_getter(attr_name)
      define_setter(attr_name)
    end
  end
end
