class TokenStream
  def initialize(tokens)
    @tokens = tokens.dup
    @index = 0
    @eof = false
  end

  def next
    raise StopIteration if @index >= @tokens.length
    token = @tokens[@index]
    @index += 1
    token
  end

  def peek
    raise StopIteration if @index >= @tokens.length
    @tokens[@index]
  end

  def rewind
    @index = 0
  end
end
